<?php
function pager($total,$number,$params){$pages=max(1,(int)ceil($total/20));echo '<div class="record-pager"><span>'.($total?($number-1)*20+1:0).'?'.min($number*20,$total).' of '.$total.' records</span><div>';foreach(['Previous'=>$number-1,'Next'=>$number+1] as $label=>$target){if($target<1||$target>$pages)echo '<span class="pager-disabled">'.$label.'</span>';else echo '<a class="button" href="?'.h(http_build_query(array_merge($params,['p'=>$target]))).'">'.$label.'</a>';}echo '<span>Page '.$number.' of '.$pages.'</span></div></div>';}
function page_number($total){$value=filter_input(INPUT_GET,'p',FILTER_VALIDATE_INT);return min(max(1,(int)$value),max(1,(int)ceil($total/20)));}
$latest=$db->query('SELECT MAX(received_at) FROM security_events')->fetchColumn() ?: 'No events yet';
$rules=detection_rules();
function panel_start($title,$subtitle='',$export=''){echo '<article class="panel module-panel"><div class="panel-heading"><div><h2>'.h($title).'</h2><p>'.h($subtitle).'</p></div>';if($export!=='')echo '<div class="export-actions"><a class="button export-button" href="?export='.h($export).'&amp;format=csv"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m0 0 4-4m-4 4-4-4M5 17v3h14v-3"/></svg>CSV</a><a class="button export-button docx-button" href="?export='.h($export).'&amp;format=docx"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h7l5 5v13H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Zm7 0v5h5M9 13h6m-6 4h6"/></svg>DOCX</a></div>';echo '</div>';}
function daily_chart($db,$days=30){$values=[];for($i=$days-1;$i>=0;$i--)$values[date('Y-m-d',strtotime('-'.$i.' days'))]=0;foreach($db->query('SELECT DATE(occurred_at) d,COUNT(*) n FROM security_events WHERE occurred_at>=CURDATE()-INTERVAL 29 DAY GROUP BY d') as $r)if(isset($values[$r['d']]))$values[$r['d']]=(int)$r['n'];$max=max(1,max($values));echo '<div class="report-chart" role="img" aria-label="Daily collected event counts">';foreach($values as $date=>$n)echo '<div tabindex="0" title="'.h($date.': '.$n.' events').'" style="height:'.($n?max(2,100*$n/$max):0).'%;min-height:2px"><span class="chart-tooltip">'.h($date.': '.$n).'</span></div>';echo '</div><p class="chart-caption">'.h(array_key_first($values)).' to '.h(array_key_last($values)).' / Hover or focus a bar for its count.</p>';}
?>
